export const SQL_SCHEMA = "-- LeadLens schema (Postgres / Supabase). Compatible with the shared Neovia lead table.\n-- Not executed in the v1 demo; displayed in the trace drawer and validated by tests.\n\ncreate table client (\n  id               text primary key,\n  name             text not null,\n  city             text not null,\n  industry         text not null,\n  plan             text not null check (plan in ('care_basic', 'care_growth', 'leadlens')),\n  logo_url         text,\n  report_day       int  not null default 1 check (report_day between 1 and 28),\n  review_required  boolean not null default true,\n  onboarded_month  date not null\n);\n\ncreate table connector (\n  id            text primary key,\n  client_id     text not null references client (id),\n  type          text not null check (type in\n                  ('website_forms', 'whatsapp_bot', 'meta_lead_ads', 'callcatch', 'slotpay', 'gbp_manual', 'google_sheet')),\n  config_json   jsonb not null default '{}'::jsonb,\n  last_sync_at  timestamptz,\n  status        text not null check (status in ('healthy', 'warning', 'failed')),\n  message       text not null default ''\n);\n\n-- Every enquiry exactly as received, before de-duplication.\ncreate table raw_enquiry (\n  id                text primary key,\n  client_id         text not null references client (id),\n  source            text not null check (source in ('instagram', 'google', 'calls', 'website', 'whatsapp')),\n  source_record_id  text not null,\n  phone_hash        text not null,           -- SHA-256(E.164 number || per-client salt)\n  payload           jsonb not null default '{}'::jsonb,\n  received_at       timestamptz not null\n);\ncreate index raw_enquiry_client_phone_idx on raw_enquiry (client_id, phone_hash);\n\n-- One row per unique enquiry (raw enquiries sharing a phone_hash within 30 days are merged; first touch wins).\ncreate table lead (\n  id                 text primary key,\n  number             int  not null,\n  client_id          text not null references client (id),\n  source             text not null check (source in ('instagram', 'google', 'calls', 'website', 'whatsapp')),\n  campaign           text not null,\n  created_at         timestamptz not null,\n  first_response_at  timestamptz,\n  site_visit_at      timestamptz,\n  closed_at          timestamptz,\n  stage              text not null check (stage in ('new', 'contacted', 'site_visit', 'won', 'lost')),\n  deal_value         numeric(12, 0),\n  outcome_reason     text check (outcome_reason in ('price', 'timeline', 'competitor', 'area', 'no_response', 'other')),\n  phone_hash         text not null,\n  name_masked        text not null,\n  phone_masked       text not null,\n  locality           text,\n  requirement        text,\n  property           text,\n  budget_band        text,\n  owner              text,\n  merged_raw_ids     text[] not null default '{}',\n  unique (client_id, number)\n);\ncreate index lead_client_created_idx on lead (client_id, created_at);\n\ncreate table ad_spend (\n  id         text primary key,\n  client_id  text not null references client (id),\n  month      date not null,\n  platform   text not null check (platform in ('meta', 'google')),\n  amount     numeric(12, 0) not null,\n  unique (client_id, month, platform)\n);\n\ncreate table care_activity (\n  id         text primary key,\n  client_id  text not null references client (id),\n  month      date not null,\n  type       text not null check (type in ('post', 'update', 'fix', 'uptime')),\n  count      numeric(8, 2) not null,         -- uptime is stored as a percentage, e.g. 99.97\n  unique (client_id, month, type)\n);\n\ncreate table gbp_metrics (\n  client_id         text not null references client (id),\n  month             date not null,\n  calls             int not null,\n  direction_requests int not null,\n  website_clicks    int not null,\n  source            text not null check (source in ('api', 'manual')),\n  primary key (client_id, month)\n);\n\ncreate table monthly_report (\n  id                             text primary key,   -- e.g. LL-UN-2026-10\n  client_id                      text not null references client (id),\n  month                          date not null,\n  metrics_json                   jsonb,\n  narrative_json                 jsonb,\n  narrative_source               text not null default 'template' check (narrative_source in ('llm', 'template')),\n  guard_result                   jsonb,\n  pdf_url                        text,\n  status                         text not null check (status in ('generated', 'in_review', 'approved', 'sent', 'blocked')),\n  generated_at                   timestamptz,\n  sent_at                        timestamptz,\n  data_changed_since_generation  boolean not null default false,\n  unique (client_id, month)\n);\n";
export const SQL_RLS = "-- Row-level security: a client user sees only rows with their own client_id.\n-- Neovia admins (JWT role = 'neovia_admin') see every client.\n-- Supabase: auth.jwt() returns the caller's JWT claims.\n\ncreate schema if not exists app;\n\ncreate or replace function app.current_client_id() returns text\nlanguage sql stable as $$ select nullif(auth.jwt() ->> 'client_id', '') $$;\n\ncreate or replace function app.is_neovia_admin() returns boolean\nlanguage sql stable as $$ select coalesce(auth.jwt() ->> 'role', '') = 'neovia_admin' $$;\n\nalter table client         enable row level security;\nalter table connector      enable row level security;\nalter table raw_enquiry    enable row level security;\nalter table lead           enable row level security;\nalter table ad_spend       enable row level security;\nalter table care_activity  enable row level security;\nalter table gbp_metrics    enable row level security;\nalter table monthly_report enable row level security;\n\ncreate policy client_isolation on client for select\n  using (app.is_neovia_admin() or id = app.current_client_id());\n\ncreate policy connector_isolation on connector for select\n  using (app.is_neovia_admin() or client_id = app.current_client_id());\n\ncreate policy raw_enquiry_isolation on raw_enquiry for select\n  using (app.is_neovia_admin() or client_id = app.current_client_id());\n\ncreate policy lead_isolation on lead for select\n  using (app.is_neovia_admin() or client_id = app.current_client_id());\n\n-- Owners may record outcomes (WON / LOST) on their own leads only.\ncreate policy lead_owner_outcome on lead for update\n  using (client_id = app.current_client_id())\n  with check (client_id = app.current_client_id());\n\ncreate policy ad_spend_isolation on ad_spend for select\n  using (app.is_neovia_admin() or client_id = app.current_client_id());\n\ncreate policy care_activity_isolation on care_activity for select\n  using (app.is_neovia_admin() or client_id = app.current_client_id());\n\ncreate policy gbp_metrics_isolation on gbp_metrics for select\n  using (app.is_neovia_admin() or client_id = app.current_client_id());\n\n-- Owners see only reports that have been sent; admins see the whole queue.\ncreate policy monthly_report_isolation on monthly_report for select\n  using (app.is_neovia_admin() or (client_id = app.current_client_id() and status = 'sent'));\n";
export const SQL_VIEWS_ALL = "-- Metric views. Every metric in src/lib/metrics/* mirrors one of these with identical semantics.\n-- All views use security_invoker so the RLS policies in rls.sql apply to the caller.\n-- Month = calendar month of lead.created_at in Asia/Kolkata (cohort basis).\n\n-- @view v_lead_base\ncreate view v_lead_base with (security_invoker = true) as\nselect\n  l.*,\n  (date_trunc('month', l.created_at at time zone 'Asia/Kolkata'))::date as month,\n  extract(epoch from (l.first_response_at - l.created_at)) / 60.0       as response_min,\n  -- the report goes out at 9:00 AM IST on the 1st of the following month\n  ((date_trunc('month', l.created_at at time zone 'Asia/Kolkata') + interval '1 month' + interval '9 hours')\n     at time zone 'Asia/Kolkata')                                       as report_time\nfrom lead l;\n\n-- @view v_monthly_headline\ncreate view v_monthly_headline with (security_invoker = true) as\nwith leads as (\n  select\n    client_id,\n    month,\n    count(*)::int                                                       as enquiries,\n    count(*) filter (where first_response_at is not null)::int          as contacted,\n    count(*) filter (where site_visit_at is not null)::int              as site_visits,\n    count(*) filter (where stage = 'won')::int                          as won,\n    coalesce(sum(deal_value) filter (where stage = 'won'), 0)           as revenue_won,\n    percentile_cont(0.5) within group (order by response_min::float8)   as median_response_min\n  from v_lead_base\n  group by client_id, month\n),\nraw as (\n  select client_id,\n         (date_trunc('month', received_at at time zone 'Asia/Kolkata'))::date as month,\n         count(*)::int as raw_enquiries\n  from raw_enquiry\n  group by 1, 2\n)\nselect\n  l.client_id,\n  l.month,\n  coalesce(r.raw_enquiries, 0)                      as raw_enquiries,\n  l.enquiries,\n  coalesce(r.raw_enquiries, 0) - l.enquiries        as duplicates_merged,\n  l.contacted,\n  l.site_visits,\n  l.won,\n  l.revenue_won,\n  l.median_response_min\nfrom leads l\nleft join raw r using (client_id, month);\n\n-- @view v_source_breakdown\ncreate view v_source_breakdown with (security_invoker = true) as\nselect\n  client_id,\n  month,\n  source,\n  count(*)::int                                                         as enquiries,\n  count(*) filter (where first_response_at is not null)::int            as contacted,\n  count(*) filter (where stage = 'won')::int                            as won,\n  coalesce(sum(deal_value) filter (where stage = 'won'), 0)             as revenue_won,\n  round(100.0 * count(*) filter (where stage = 'won') / count(*), 1)    as conversion_pct\nfrom v_lead_base\ngroup by client_id, month, source;\n\n-- @view v_weekly_enquiries\ncreate view v_weekly_enquiries with (security_invoker = true) as\nselect\n  client_id,\n  month,\n  ((extract(day from created_at at time zone 'Asia/Kolkata')::int - 1) / 7) + 1 as week_no,\n  count(*)::int as enquiries\nfrom v_lead_base\ngroup by 1, 2, 3;\n\n-- @view v_speed_to_lead\ncreate view v_speed_to_lead with (security_invoker = true) as\nselect\n  client_id,\n  month,\n  count(*) filter (where first_response_at is not null)::int                       as contacted,\n  percentile_cont(0.5) within group (order by response_min::float8)                as median_min,\n  count(*) filter (where response_min <= 15)::int                                  as within_15,\n  count(*) filter (where response_min < 5)::int                                    as b_lt5,\n  count(*) filter (where response_min >= 5 and response_min <= 15)::int            as b_5_15,\n  count(*) filter (where response_min > 15 and response_min <= 60)::int            as b_15_60,\n  count(*) filter (where response_min > 60 and response_min <= 240)::int           as b_1_4h,\n  count(*) filter (where response_min > 240 and response_min <= 1440)::int         as b_4_24h,\n  count(*) filter (where response_min is null or response_min > 1440)::int         as b_gt24_or_never\nfrom v_lead_base\ngroup by client_id, month;\n\n-- @view v_funnel\n-- Stages are counted from timestamps (contacted -> site visit -> won), not from the current stage.\ncreate view v_funnel with (security_invoker = true) as\nselect\n  client_id,\n  month,\n  count(*)::int                                                         as enquiries,\n  count(*) filter (where first_response_at is not null)::int            as contacted,\n  count(*) filter (where site_visit_at is not null)::int                as site_visit,\n  count(*) filter (where stage = 'won')::int                            as won\nfrom v_lead_base\ngroup by client_id, month;\n\n-- @view v_missed_opportunities\n-- Never contacted and older than 24h at report time, or first response more than 24h after creation.\ncreate view v_missed_opportunities with (security_invoker = true) as\nselect\n  client_id,\n  month,\n  id as lead_id,\n  number,\n  source,\n  created_at,\n  first_response_at,\n  case when first_response_at is null then 'never_contacted' else 'late_response' end as reason\nfrom v_lead_base\nwhere (first_response_at is null and created_at < least(now(), report_time) - interval '24 hours')\n   or (first_response_at - created_at > interval '24 hours');\n\n-- @view v_cost_per_lead\n-- Cost per lead = platform spend / leads from that source. Cost per win = platform spend / wins from that source.\ncreate view v_cost_per_lead with (security_invoker = true) as\nwith src as (\n  select\n    client_id,\n    month,\n    source,\n    case source when 'instagram' then 'meta' when 'google' then 'google' end as platform,\n    count(*)::int                                  as leads,\n    count(*) filter (where stage = 'won')::int     as wins\n  from v_lead_base\n  where source in ('instagram', 'google')\n  group by 1, 2, 3, 4\n)\nselect\n  s.client_id,\n  s.month,\n  s.source,\n  s.platform,\n  coalesce(a.amount, 0)                               as spend,\n  s.leads,\n  s.wins,\n  round(a.amount / nullif(s.leads, 0))                as cost_per_lead,\n  round(a.amount / nullif(s.wins, 0))                 as cost_per_win\nfrom src s\nleft join ad_spend a\n  on a.client_id = s.client_id and a.month = s.month and a.platform = s.platform;\n\n-- @view v_campaigns\ncreate view v_campaigns with (security_invoker = true) as\nselect\n  client_id,\n  month,\n  source,\n  campaign,\n  count(*)::int                              as enquiries,\n  count(*) filter (where stage = 'won')::int as won\nfrom v_lead_base\ngroup by client_id, month, source, campaign;\n\n-- @view v_lost_reasons\ncreate view v_lost_reasons with (security_invoker = true) as\nselect\n  client_id,\n  month,\n  outcome_reason,\n  count(*)::int as leads\nfrom v_lead_base\nwhere stage = 'lost'\ngroup by client_id, month, outcome_reason;\n";
